mapper.select:
SELECT COUNT(*) FROM inquiries WHERE is_deleted = FALSE
AND title LIKE CONCAT('%', #{search}, '%')
AND status = #{status}

mapper.insert:
INSERT INTO inquiry_attachments (
inquiry_id, inquiry_answer_id, file_name, original_file_name, file_path, file_type, file_size, description, is_downloadable, download_count, is_deleted, uploaded_at
) VALUES (
#{inquiryId}, #{inquiryAnswerId}, #{fileName}, #{originalFileName}, #{filePath}, #{fileType}, #{fileSize}, #{description}, #{downloadable}, #{downloadCount}, #{deleted}, NOW()
)

mapper.update:
UPDATE inquiry_attachments 
SET download_count = download_count + 1
WHERE id = #{attachmentId}

mapper.insert:
INSERT INTO inquiry_answers (
    inquiry_id, admin_id, answer, has_attachment, is_edited, is_read_by_user, created_at, updated_at
) VALUES (
    #{inquiryId}, #{adminId}, #{answer}, #{hasAttachment}, #{edited}, #{readByUser}, NOW(), NOW()
)

mapper.update:
UPDATE inquiry_answers 
SET is_read_by_user = TRUE 
WHERE inquiry_id = #{inquiryId}

mapper.select:
SELECT i.id, i.user_id as userId, i.title, i.content, i.category, i.context_type as contextType, i.target_id as targetId, i.has_attachment as hasAttachment, i.is_urgent as urgent, i.is_reviewed as reviewed, i.answered_at as answeredAt, i.status, i.is_deleted as deleted, i.created_at as createdAt, i.updated_at as updatedAt, u.username as writerName FROM inquiries i LEFT JOIN users u ON i.user_id = u.id WHERE i.is_deleted = 0 AND i.user_id = #{userId}
ORDER BY i.created_at ASC
ORDER BY i.created_at DESC
LIMIT #{limit} OFFSET #{offset}
